    84	static const char* GetEspNnDepthwiseCandidateReason(
    85	    const TfLiteTensor* input, const TfLiteTensor* filter,
    86	    const TfLiteTensor* output, const TfLiteDepthwiseConvParams& params,
    87	    const OpDataConv& op_data) {
    88	  if (input->type != kTfLiteInt8 || filter->type != kTfLiteInt8 ||
    89	      output->type != kTfLiteInt8) {
    90	    return "type";
    91	  }
    92	
    93	  if (input->dims->size != 4 || filter->dims->size != 4 ||
    94	      output->dims->size != 4 || input->dims->data[0] != 1 ||
    95	      output->dims->data[0] != 1) {
    96	    return "shape";
    97	  }
    98	
    99	  if (params.depth_multiplier != 1 ||
   100	      filter->dims->data[3] != input->dims->data[3] ||
   101	      output->dims->data[3] != input->dims->data[3]) {
   102	    return "depth_multiplier";
   103	  }
   104	
   105	  if (params.dilation_width_factor != 1 ||
   106	      params.dilation_height_factor != 1) {
   107	    return "dilation";
   108	  }
   109	
   110	  /*
   111	   * Admit only shapes assigned to model-specific hardware verify profiles.
   112	   * The 4-class model uses 12/16 channels; S3-large uses the native
   113	   * 32/64-channel padded s8 assembly paths. Selection by tensor ID remains
   114	   * mandatory.
   115	   */
   116	  if (filter->dims->data[1] != 3 || filter->dims->data[2] != 3) {
   117	    return "kernel";
   118	  }
   119	
   120	  if (params.stride_width != 1 || params.stride_height != 1) {
   121	    return "stride";
   122	  }
   123	
   124	  if (op_data.padding.width != 1 || op_data.padding.height != 1) {
   125	    return "padding";
   126	  }
   127	
   128	  const int channels = input->dims->data[3];
   129	  if (channels != 12 && channels != 16 && channels != 32 && channels != 64) {
   130	    return "channels";
   131	  }
   132	
   133	  return nullptr;
   134	}
