   136	static const char* GetEspNnDepthwiseRuntimeReason(const void* input,
   137	                                                   const void* output,
   138	                                                   const void* scratch) {
   139	  if (!IsAligned(input, 16)) {
   140	    return "input_alignment";
   141	  }
   142	
   143	  if (!IsAligned(output, 16)) {
   144	    return "output_alignment";
   145	  }
   146	
   147	  if (!IsAligned(scratch, 16)) {
   148	    return "scratch_alignment";
   149	  }
   150	
   151	  return nullptr;
   152	}
