                {
                  out = arm_nn_mat_mult_kernel_s8_s16(filter_data,
                                                      buffer_a,
                                                      output_ch,
                                                      output_shift,
                                                      output_mult,
                                                      out_offset,
                                                      out_activation_min,
                                                      out_activation_max,
                                                      rhs_cols,
                                                      aligned_rhs_cols,
                                                      bias_data,
